import { DatabaseSync } from 'node:sqlite';
let enabled=false;
const counts=new Map();
globalThis.__regroupSql={start(){counts.clear();enabled=true;},stop(){enabled=false;return [...counts].map(([sql,value])=>({sql,...value}));}};
const prepare=DatabaseSync.prototype.prepare;
DatabaseSync.prototype.prepare=function(sql,...rest){
 const statement=prepare.call(this,sql,...rest);
 const key=sql.replace(/collection_query_\d+/g,'collection_query').replace(/\s+/g,' ').trim();
 for(const method of ['all','get','run']) {
  const original=statement[method];
  statement[method]=function(...args){
   if(!enabled)return original.apply(this,args);
   const at=performance.now();const value=original.apply(this,args);
   const entry=counts.get(key)??{calls:0,rows:0,ms:0};entry.calls++;entry.rows+=Array.isArray(value)?value.length:method==='get'&&value?1:0;entry.ms+=performance.now()-at;counts.set(key,entry);return value;
  };
 }
 return statement;
};

