import fs from 'node:fs';
import {openSqliteOrThrow} from '/tmp/p190/sidebar/release/packages/server/dist/storage/sqlite.js';
import {SessionCollectionSql} from '/tmp/p190/sidebar/release/packages/server/dist/services/session-collection-sql.js';
const results=[];
for(const count of [500,50000]) {
 const db=openSqliteOrThrow(':memory:');const sql=new SessionCollectionSql(db);sql.beginReplacement();
 db.transaction(()=>{for(let i=0;i<count;i++)sql.put({id:String(i),projectId:'p'+(i%200),projectName:'P',provider:'claude',updatedAt:new Date(1794430000000-i*1000).toISOString()},null,i,false,false);});
 await sql.finishReplacement(new AbortController().signal);
 const p=sql.prefix;const original=`SELECT id,updated_ms FROM ${p}_rows WHERE 1 AND archived=0 AND attention=0 AND id IN (SELECT value FROM json_each(?)) ORDER BY updated_ms DESC,id LIMIT ?`;
 const candidate=`SELECT r.id,r.updated_ms FROM json_each(?) AS wanted CROSS JOIN ${p}_rows AS r ON r.id=wanted.value WHERE r.archived=0 AND r.attention=0 ORDER BY r.updated_ms DESC,r.id LIMIT ?`;
